def calculate_S(N):
    S = 0
    N_plus_1 = N + 1
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S += (a * b) // N_plus_1
    return S

def calculate_target(N):
    return (N**3 - N**2 + 2) / 4

print(f"N=1: S(1) = {calculate_S(1)}, Target = {calculate_target(1)}")
print(f"N=2: S(2) = {calculate_S(2)}, Target = {calculate_target(2)}")
print(f"N=3: S(3) = {calculate_S(3)}, Target = {calculate_target(3)}")
print(f"N=4: S(4) = {calculate_S(4)}, Target = {calculate_target(4)}")
